// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/v2/convert.ts`. Edit the source and run `just generate`.
// The pure conversion of one change folder from schema 1 to schema 2.
// The input is the text of each file of the folder, and the output is the new text of each file that changes.
// It reads no file and runs no process, so P49 can run it on the store and a test can run it on a fixture.
// Plain data and pure functions only.

import type { Lane, LaneEvent } from "../../../../kernel/spec-store.ts";
import {
  eventLine2,
  eventsHeader2,
  FRONT_SCHEMA_2,
  type StateEvent,
} from "../../../../kernel/state-events.ts";
import { parsePackage } from "../plan.ts";
import { type Front, renderFront } from "./front.ts";
import type { ChangeState, PackageState } from "./states.ts";

/** The text of each file of a change folder, by path relative to the folder. */
export type FolderFiles = Readonly<Record<string, string>>;

/** One file that the conversion could not convert. The file stays unchanged. */
export interface ConvertFailure {
  readonly file: string;
  readonly message: string;
}

/** The result of the conversion: the new texts, the files to remove, and the failures. */
export interface Conversion {
  /** The new text of each file that changes, by path relative to the folder. */
  readonly files: Record<string, string>;
  readonly removed: string[];
  readonly failures: ConvertFailure[];
}

/** The note on a `verified` event that comes from a lane `review`. */
export const NO_VERIFY_NOTE =
  "Converted from schema 1, which had no verify record (no SHA, no exit status).";

const EVENTS = "events.jsonl";
const WAVE_HEADING = /^##\s+Wave\s+(\d+)\b/;
const LIST_ITEM = /^-\s+\[[ xX]\]\s+(P[0-9A-Za-z]+)\b/;
const HEADING = /^#\s+(?:P[0-9A-Za-z]+\s+)?(.+?)\s*$/m;

/** The wave number of each package, from the headings and the list items of `packages.md`. */
const wavesOf = (text: string): Map<string, string> => {
  const waves = new Map<string, string>();
  let wave: string | null = null;
  for (const line of text.split("\n")) {
    wave = WAVE_HEADING.exec(line)?.[1] ?? wave;
    const id = LIST_ITEM.exec(line)?.[1];
    if (id !== undefined && wave !== null) waves.set(id, wave);
  }
  return waves;
};

/** The state events of a package in schema 2 for one event of schema 1. */
const convertEvent = (event: LaneEvent): StateEvent => {
  const base = { at: event.at, package: event.package };
  const findings = event.findings ? { findings: event.findings } : {};
  const note = event.note ? { note: event.note } : {};
  if (event.verdict === "approve")
    return { ...base, state: "approved", ...findings, ...note };
  if (event.verdict === "reject")
    return {
      ...base,
      state: "doing",
      ...findings,
      decision: "fix-code",
      ...note,
    };
  if (event.lane === "review")
    return {
      ...base,
      state: "verified",
      note: [event.note, NO_VERIFY_NOTE].filter(Boolean).join(" "),
    };
  const state: PackageState = event.lane satisfies Exclude<Lane, "review">;
  return { ...base, state, ...note };
};

/** The events of schema 1 in `text`, or the failure when the header or a line is not valid. */
const parseOldEvents = (
  text: string,
): { events: LaneEvent[] } | { failure: string } => {
  const lines = text.split("\n").filter((raw) => raw.trim() !== "");
  const torn = !text.endsWith("\n");
  const events: LaneEvent[] = [];
  for (const [i, raw] of lines.entries()) {
    let value: unknown;
    try {
      value = JSON.parse(raw);
    } catch {
      if (torn && i === lines.length - 1) break;
      return { failure: `line ${i + 1} is not JSON` };
    }
    if (i === 0) {
      const schema = (value as { schema?: unknown }).schema;
      if (schema !== 1)
        return { failure: `the header has schema ${String(schema)}, not 1` };
      continue;
    }
    events.push(value as LaneEvent);
  }
  return { events };
};

/** The front matter and the body of a schema 1 brief: the text after the closing `---` line. */
const bodyOf = (text: string): string => {
  const lines = text.split("\n");
  const close = lines.findIndex((l, i) => i > 0 && l === "---");
  return lines.slice(close + 1).join("\n");
};

/** True when `text` starts with a front matter block. */
const hasFront = (text: string): boolean => text.startsWith("---\n");

const convertBrief = (
  text: string,
  waves: ReadonlyMap<string, string>,
  states: ReadonlyMap<string, string>,
): { text: string } | { failure: string } => {
  const parsed = parsePackage(text);
  if (!parsed.ok)
    return {
      failure: `not a package of schema 1: ${parsed.errors.map((e) => e.message).join(" ")}`,
    };
  const { front } = parsed.value;
  const body = bodyOf(text);
  const title = HEADING.exec(body)?.[1];
  const wave = waves.get(front.id);
  if (title === undefined) return { failure: "the brief has no heading" };
  if (wave === undefined)
    return { failure: `\`packages.md\` has no wave for \`${front.id}\`` };
  const values: Front = {
    schema: FRONT_SCHEMA_2,
    kind: "package",
    id: front.id,
    title,
    wave,
    deps: front.deps,
    owns: front.owns,
    satisfies: [],
    verify: front.verify,
    agent: front.agent,
    status: states.get(front.id) ?? "planned",
  };
  return { text: renderFront("package", values) + body };
};

/** The files of the folder that are package briefs, in order. */
const briefsOf = (files: FolderFiles): string[] =>
  Object.keys(files)
    .filter((f) => /^packages\/[^/]+\.md$/.test(f))
    .sort();

/**
 * Converts the change folder `files` of the change `id` from schema 1 to schema 2.
 * `verify` is the `verify` command that the new `change.md` gets.
 * A file that cannot convert stays out of `files` and has an entry in `failures`.
 * The size is `large` when the folder has `design.md`, and `medium` when it has none.
 * The status of the change is `implementing` when the log has an event, else `draft`.
 */
export const convertChange = (
  files: FolderFiles,
  id: string,
  verify: string,
): Conversion => {
  const out: Conversion = { files: {}, removed: [], failures: [] };
  const fail = (file: string, message: string): void => {
    out.failures.push({ file, message });
  };
  const old = parseOldEvents(files[EVENTS] ?? "");
  if ("failure" in old) fail(EVENTS, old.failure);
  const oldEvents = "events" in old ? old.events : [];
  const converted = oldEvents.map(convertEvent);
  const states = new Map<string, string>();
  for (const e of converted) if (e.package) states.set(e.package, e.state);
  const first = converted[0];
  const status: ChangeState = first ? "implementing" : "draft";
  const changeEvents: StateEvent[] = first
    ? [{ at: first.at, state: status, note: "Converted from schema 1." }]
    : [];
  if (EVENTS in files && !("failure" in old))
    out.files[EVENTS] =
      eventsHeader2() +
      [...changeEvents, ...converted].map(eventLine2).join("");
  const waves = wavesOf(files["packages.md"] ?? "");
  for (const file of briefsOf(files)) {
    const result = convertBrief(files[file] ?? "", waves, states);
    if ("failure" in result) fail(file, result.failure);
    else out.files[file] = result.text;
  }
  const change = files["change.md"];
  if (change !== undefined) {
    if (hasFront(change))
      fail("change.md", "the file has front matter already");
    else
      out.files["change.md"] =
        renderFront("change", {
          schema: FRONT_SCHEMA_2,
          kind: "change",
          id,
          size: "design.md" in files ? "large" : "medium",
          status,
          verify,
        }) +
        "\n" +
        change;
  }
  const design = files["design.md"];
  if (design !== undefined) {
    if (hasFront(design))
      fail("design.md", "the file has front matter already");
    else
      out.files["design.md"] =
        renderFront("design", { schema: FRONT_SCHEMA_2, kind: "design", id }) +
        "\n" +
        design;
  }
  if ("packages.md" in files) out.removed.push("packages.md");
  return out;
};
